import { KolaboroV1 } from 'https://kolaboro.com/sdk/v1/kolaboro-v1.mjs';
const k = new KolaboroV1({ verify: true });   // checks the Ed25519 signature of every answer
const p = await k.getProject({ slug: 'amani-melasti' });
const hits = await k.find({ q: 'proyectos en Dubái', lang: 'es' });
const proof = await k.getInclusionProof({ project: 'amani-melasti' });
console.log(p.name, hits.count, proof.tree_head.root, k.last.signature);
